import fs from 'node:fs/promises';
import path from 'node:path';

const sourcePath = process.argv[2] || 'work/nps_data.json';
const output = process.argv[3] || 'outputs/medallia_cx_nps_2026-08-14/medallia_cx_nps_dashboard.html';
const source = JSON.parse(await fs.readFile(sourcePath, 'utf8'));
const samiData = source.sami || null;
const spanishMonths = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
const formatReportTimestamp = (date) => `${String(date.getDate()).padStart(2, '0')} ${spanishMonths[date.getMonth()]} ${date.getFullYear()} · ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
const reportUpdatedAt = source.report_updated_at || formatReportTimestamp(new Date());
const feedbackRows = source.feedback_model.rows.map(x => ({
  month: x.month, segment: x.segment, klass: x.nps_class,
  category: x.category_local || x.category,
  categoryLocal: x.category_local || x.category,
  categoryOllama: x.category_ollama || null,
  score: x.score, feedback: x.feedback
}));
const responseRows = source.records.map(x => ({
  month: String(x['Response Date']).slice(0, 7),
  segment: x['Product Segment'], klass: x['NPS Class'], score: x.Score
}));
const preferredSegmentOrder = [
  'rNPS / Relación',
  'pNPS Internet',
  'pNPS Mobile - Contrato',
  'pNPS Mobile - Prepago',
  'tNPS - Pay - Invoice',
  'tNPS - Pay - Full Journey',
  'tNPS - Buy',
  'tNPS - Install - Full Install',
  'tNPS - Install - Self Install',
  'tNPS - Change',
  'tNPS - Exit',
  'tNPS - Help - CC',
  'tNPS - Help - Store',
  'tNPS - Help - General',
  'tNPS - Help - Technician',
];
const availableSegments = new Set(responseRows.map(x => x.segment));
const segments = [
  'Total',
  ...preferredSegmentOrder.filter(segment => availableSegments.has(segment)),
  ...[...availableSegments].filter(segment => !preferredSegmentOrder.includes(segment)),
];
if (samiData) {
  const rnpsIndex = segments.indexOf('rNPS / Relación');
  segments.splice(rnpsIndex >= 0 ? rnpsIndex + 1 : 1, 0, 'SAMI');
}
